thread_local CUmodule g_entity_fused_modules[4] = {};
thread_local CUfunction g_entity_fused_functions[4] = {};
static const unsigned int entity_fused_shared[4] = {8192,10240,10240,10240};
static const unsigned int entity_fused_threads[4] = {128,128,128,128};
static void entity_fused_init() {
    int mask = getenv("NH_ENTITY_FUSED") ? atoi(getenv("NH_ENTITY_FUSED")) : 0;
    if (!mask) return;
    int device; cudaDeviceProp properties;
    assert(cudaGetDevice(&device) == cudaSuccess);
    assert(cudaGetDeviceProperties(&properties, device) == cudaSuccess);
    assert(properties.major == 8 && properties.minor == 9);
    const void* data[4] = {entity_fused_inventory_cubin,entity_fused_monster_cubin,entity_fused_item_cubin,entity_fused_spell_cubin};
    for (int i=0; i<4; i++) {
        if (!(mask & (1<<i)) || g_entity_fused_functions[i]) continue;
        assert(cuModuleLoadData(&g_entity_fused_modules[i], data[i]) == CUDA_SUCCESS);
        assert(cuModuleGetFunction(&g_entity_fused_functions[i], g_entity_fused_modules[i], "entity_fused") == CUDA_SUCCESS);
        fprintf(stderr,"ENTITY_FUSED_READY branch=%d shared=%u\n",i,entity_fused_shared[i]);
    }
}
static bool entity_fused_try(int branch, void* x, void* w1, void* b1, void* w2,
        void* b2, void* gid, void* concat, void* amax, int B, cudaStream_t stream) {
    CUfunction f = g_entity_fused_functions[branch];
    if (!f) return false;
    void* scratch = NULL;
    void* args[] = {&x,&w1,&b1,&w2,&b2,&gid,&concat,&amax,&scratch,&scratch};
    assert(cuLaunchKernel(f,B,1,1,entity_fused_threads[branch],1,1,
        entity_fused_shared[branch],stream,args,NULL) == CUDA_SUCCESS);
    return true;
}
